export const EXPANSION_LOVERS = ["愛の鞭", "快感", "ベッド", "ホテル", "朝まで", "裸", "キス", "唇", "抱いて", "もっと", "奥まで", "感じる", "溶ける", "甘い", "吐息", "秘密", "いけないこと", "二人だけの", "愛し合う", "脱いで", "腰", "胸", "指先", "濡れる", "敏感", "シーツ", "夜の", "大人の", "色気", "誘惑"];
export const EXPANSION_STALKER = ["監視", "盗聴", "GPS", "逃がさない", "ずっと見てる", "部屋の隅", "鍵", "閉じ込める", "足跡", "匂い", "髪の毛", "爪", "血", "呪い", "殺す", "死んで", "死体", "心中", "重い", "狂気", "ストーカー", "束縛", "スマホ見せて", "パスワード", "誰といたの", "愛が重い", "ヤンデレ", "深夜", "待ち伏せ", "後ろ"];
export const EXPANSION_GESU = ["お金", "パパ", "愛人", "浮気", "不倫", "慰謝料", "キャバクラ", "ホスト", "借金", "貢ぐ", "ATM", "札束", "1億円", "ヒモ", "養って", "都合のいい", "金づる", "財産", "遺産", "離婚", "ギャンブル", "パチンコ", "風俗", "援助交際", "クズ", "最低", "ゲス", "騙す", "嘘つき", "利用する"];

const dealCards = (G, random, ctx) => {
  G.proposals = {};
  for (let i = 0; i < ctx.numPlayers; i++) {
    const pid = i.toString();
    G.proposals[pid] = null;
    
    if (pid !== G.targetPlayer) {
      let hand = [];
      for (let j = 0; j < 6; j++) {
        if (G.deck.length === 0) {
          G.deck = random.Shuffle([...G.wordPool]);
        }
        hand.push(G.deck.pop());
      }
      G.players[pid].hand = hand;
    } else {
      G.players[pid].hand = [];
    }
  }
};

const getInitialState = (ctx, setupData = {}) => {
  const players = {};
  for (let i = 0; i < ctx.numPlayers; i++) {
    players[i.toString()] = { rings: 3, hand: [] };
  }
  
  return {
    gameState: 'lobby', // 'lobby', 'thinking', 'presenting', 'results', 'game_over'
    players,
    targetPlayer: null,
    deck: [],
    wordPool: [],
    proposals: {},
    roundWinner: null,
    nextMatchId: null,
    selectedExpansions: setupData.expansions || [],
  };
};

export const Propose = {
  name: 'propose',
  
  setup: ({ ctx, setupData }) => getInitialState(ctx, setupData),

  turn: {
    activePlayers: { all: 'play' }
  },

  moves: {
    toggleExpansion: ({ G }, expansionName) => {
      if (G.gameState !== 'lobby') return;
      if (G.selectedExpansions.includes(expansionName)) {
        G.selectedExpansions = G.selectedExpansions.filter(e => e !== expansionName);
      } else {
        G.selectedExpansions.push(expansionName);
      }
    },

    startGame: ({ G, random, ctx }) => {
      if (G.gameState !== 'lobby') return;
      
      let pool = [...RANDOM_WORDS];
      if (G.selectedExpansions.includes('lovers')) pool = pool.concat(EXPANSION_LOVERS);
      if (G.selectedExpansions.includes('stalker')) pool = pool.concat(EXPANSION_STALKER);
      if (G.selectedExpansions.includes('gesu')) pool = pool.concat(EXPANSION_GESU);
      
      G.wordPool = pool;
      G.deck = random.Shuffle([...G.wordPool]);
      
      G.targetPlayer = '0';
      dealCards(G, random, ctx);
      G.gameState = 'thinking';
    },

    submitProposal: ({ G, ctx }, playerID, sentenceArray) => {
      if (G.gameState !== 'thinking' || playerID === G.targetPlayer) return;
      G.proposals[playerID] = sentenceArray;
      
      // Check if all active proposers have submitted
      const proposers = Object.keys(G.players).filter(pid => pid !== G.targetPlayer);
      const allSubmitted = proposers.every(pid => G.proposals[pid] && G.proposals[pid].length > 0);
      
      if (allSubmitted) {
        G.gameState = 'presenting';
      }
    },

    acceptProposal: ({ G, ctx }, targetPlayerID, winnerID) => {
      // Only the target player can accept
      if (G.gameState !== 'presenting' || targetPlayerID !== G.targetPlayer) return;
      
      G.players[winnerID].rings -= 1;
      G.roundWinner = winnerID;
      
      if (G.players[winnerID].rings <= 0) {
        G.gameState = 'game_over';
      } else {
        G.gameState = 'results';
      }
    },

    nextRound: ({ G, random, ctx }) => {
      if (G.gameState !== 'results') return;
      
      // Rotate target player
      const currentIdx = parseInt(G.targetPlayer);
      G.targetPlayer = ((currentIdx + 1) % ctx.numPlayers).toString();
      
      dealCards(G, random, ctx);
      G.roundWinner = null;
      G.gameState = 'thinking';
    },

    proposeRematch: ({ G }, nextMatchId) => {
      G.nextMatchId = nextMatchId;
    }
  }
};
